import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
  return twMerge(clsx(inputs));
}

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";

export type TextSpectrumDirection = "horizontal" | "vertical" | "diagonal";

export interface TextSpectrumProps {
  /** The string to render. */
  text: string;
  /** Tag rendered as the outer element. */
  as?: keyof React.JSX.IntrinsicElements;
  /** Spectrum stop colors. First color is duplicated for seamless loops. */
  colors?: string[];
  /** Full cycle duration in seconds. Lower = faster. Default: 8. */
  duration?: number;
  /** Gradient travel axis. */
  direction?: TextSpectrumDirection;
  /** Ping-pong the wash instead of looping in one direction. */
  yoyo?: boolean;
  /** Pause the loop while the pointer is over the text. */
  pauseOnHover?: boolean;
  /** Draw an animated spectrum ring around the text. */
  showBorder?: boolean;
  /**
   * Force the infinite loop paused. When omitted, the loop runs forever while
   * visible and auto-pauses when off-screen or the tab is hidden.
   */
  paused?: boolean;
  /** Optional Tailwind class for size, weight, tracking, etc. */
  className?: string;
}

const BASE_STYLE_ID = "wensity-text-spectrum-base";

/** Chili red → coral → amber — Wensity brand spectrum. */
const DEFAULT_COLORS = ["#cd1c18", "#f15a45", "#fbbf24"] as const;

/**
 * TextSpectrum
 *
 * Multi-stop color wash for headlines. Clips a drifting linear-gradient
 * through the glyphs with `background-clip: text`. Only `background-position`
 * animates — no layout thrash, no Motion/rAF loop.
 *
 * Motion contract:
 * - Loop is CSS `linear infinite` (or `alternate` when yoyo).
 * - Default duration is 8s for a readable color drift.
 * - Auto-pauses off-screen / hidden tabs via `animation-play-state`.
 * - Optional hover pause via the same play-state path.
 * - Honours `prefers-reduced-motion` with a static mid-spectrum fill.
 */
export function TextSpectrum({
  text,
  as = "span",
  colors = [...DEFAULT_COLORS],
  duration = 8,
  direction = "horizontal",
  yoyo = true,
  pauseOnHover = false,
  showBorder = false,
  paused,
  className,
}: TextSpectrumProps) {
  const nodeRef = React.useRef<HTMLElement | null>(null);
  const borderRef = React.useRef<HTMLSpanElement | null>(null);
  const pausedPropRef = React.useRef(paused);
  const hoverPausedRef = React.useRef(false);
  const inViewRef = React.useRef(true);
  pausedPropRef.current = paused;

  const safeDuration = Math.max(1, duration);
  const stops = colors.length > 0 ? colors : [...DEFAULT_COLORS];
  // Duplicate first stop so continuous loops join cleanly.
  const gradientStops = [...stops, stops[0]].join(", ");
  const gradientAngle =
    direction === "horizontal"
      ? "to right"
      : direction === "vertical"
        ? "to bottom"
        : "to bottom right";
  const backgroundSize =
    direction === "horizontal"
      ? "300% 100%"
      : direction === "vertical"
        ? "100% 300%"
        : "300% 300%";
  const gradientImage = `linear-gradient(${gradientAngle}, ${gradientStops})`;

  React.useLayoutEffect(() => {
    ensureBaseStyles();
  }, []);

  React.useEffect(() => {
    const node = nodeRef.current;
    if (!node) return;

    let pageVisible = document.visibilityState !== "hidden";

    const syncPlayState = () => {
      const forced = pausedPropRef.current;
      const autoPause = !(inViewRef.current && pageVisible);
      const shouldPause =
        forced === true ||
        hoverPausedRef.current ||
        (forced !== false && autoPause);
      const value = shouldPause ? "true" : "false";
      node.dataset.spectrumPaused = value;
      if (borderRef.current) {
        borderRef.current.dataset.spectrumPaused = value;
      }
    };

    if (paused === true) {
      syncPlayState();
      return;
    }

    const io = new IntersectionObserver(
      (entries) => {
        inViewRef.current = entries.some((entry) => entry.isIntersecting);
        syncPlayState();
      },
      { threshold: 0.01 },
    );

    const onVisibility = () => {
      pageVisible = document.visibilityState !== "hidden";
      syncPlayState();
    };

    if (paused !== false) {
      io.observe(node);
      document.addEventListener("visibilitychange", onVisibility);
    }

    syncPlayState();

    return () => {
      io.disconnect();
      document.removeEventListener("visibilitychange", onVisibility);
    };
  }, [paused]);

  const syncHoverPause = (next: boolean) => {
    hoverPausedRef.current = next;
    const node = nodeRef.current;
    if (!node) return;

    const forced = pausedPropRef.current;
    const apply = (value: "true" | "false") => {
      node.dataset.spectrumPaused = value;
      if (borderRef.current) {
        borderRef.current.dataset.spectrumPaused = value;
      }
    };

    if (forced === true) {
      apply("true");
      return;
    }
    if (forced === false) {
      apply(next ? "true" : "false");
      return;
    }

    if (next) {
      apply("true");
      return;
    }

    const pageVisible = document.visibilityState !== "hidden";
    apply(inViewRef.current && pageVisible ? "false" : "true");
  };

  const hoverHandlers =
    pauseOnHover
      ? {
          onMouseEnter: () => {
            syncHoverPause(true);
          },
          onMouseLeave: () => {
            syncHoverPause(false);
          },
        }
      : undefined;

  const Tag = as as unknown as React.ComponentType<
    React.HTMLAttributes<HTMLElement> & {
      ref?: React.RefCallback<HTMLElement | null>;
      "data-spectrum-paused"?: "true" | "false";
      "data-spectrum-yoyo"?: "true" | "false";
      "data-spectrum-direction"?: TextSpectrumDirection;
    }
  >;

  const textNode = (
    <Tag
      ref={(node) => {
        nodeRef.current = node;
      }}
      data-spectrum-paused={paused === true ? "true" : "false"}
      data-spectrum-yoyo={yoyo ? "true" : "false"}
      data-spectrum-direction={direction}
      {...(showBorder ? undefined : hoverHandlers)}
      className={cn(
        "wensity-text-spectrum relative inline-block overflow-visible",
        "py-[0.14em] leading-[1.2]",
        "[background-clip:text] [-webkit-background-clip:text]",
        "[-webkit-text-fill-color:transparent]",
        "[box-decoration-break:clone] [-webkit-box-decoration-break:clone]",
        "[transform:translateZ(0)] [text-wrap:balance]",
        !showBorder && className,
      )}
      style={
        {
          backgroundImage: gradientImage,
          backgroundSize,
          backgroundRepeat: "repeat",
          "--wensity-spectrum-duration": `${safeDuration}s`,
        } as React.CSSProperties
      }
    >
      {text}
    </Tag>
  );

  if (!showBorder) {
    return textNode;
  }

  return (
    <span
      className={cn(
        "relative inline-flex max-w-fit items-center justify-center",
        "rounded-[0.7rem] p-px",
        className,
      )}
      {...hoverHandlers}
    >
      {/* Animated spectrum stroke */}
      <span
        ref={borderRef}
        aria-hidden
        data-spectrum-paused={paused === true ? "true" : "false"}
        data-spectrum-yoyo={yoyo ? "true" : "false"}
        data-spectrum-direction={direction}
        className="wensity-text-spectrum pointer-events-none absolute inset-0 rounded-[0.7rem]"
        style={
          {
            backgroundImage: gradientImage,
            backgroundSize,
            backgroundRepeat: "repeat",
            "--wensity-spectrum-duration": `${safeDuration}s`,
          } as React.CSSProperties
        }
      />
      {/* Solid fill: black in light, cream in dark */}
      <span
        className={cn(
          "relative z-[1] inline-flex items-center justify-center rounded-[calc(0.7rem-1px)]",
          "bg-[#0a0a0b] px-[0.55em] py-[0.22em]",
          "dark:bg-[#f4f1ea]",
        )}
      >
        {textNode}
      </span>
    </span>
  );
}

function ensureBaseStyles() {
  if (typeof document === "undefined") return;
  if (document.getElementById(BASE_STYLE_ID)) return;
  const style = document.createElement("style");
  style.id = BASE_STYLE_ID;
  style.textContent = BASE_STYLES;
  document.head.appendChild(style);
}

const BASE_STYLES = `
.wensity-text-spectrum {
  animation-name: wensity-text-spectrum-h;
  animation-duration: var(--wensity-spectrum-duration, 8s);
  animation-timing-function: linear;
  animation-iteration-count: infinite;
  animation-fill-mode: both;
  animation-play-state: running;
  animation-direction: normal;
}
.wensity-text-spectrum[data-spectrum-direction="vertical"] {
  animation-name: wensity-text-spectrum-v;
}
.wensity-text-spectrum[data-spectrum-direction="diagonal"] {
  animation-name: wensity-text-spectrum-d;
}
.wensity-text-spectrum[data-spectrum-yoyo="true"] {
  animation-direction: alternate;
}
.wensity-text-spectrum[data-spectrum-paused="true"] {
  animation-play-state: paused;
}
/*
 * Travel distance must be a whole number of gradient tiles, otherwise the
 * one-directional loop (yoyo off) snaps mid-spectrum on every restart.
 * background-position percentages resolve against (element - image), and the
 * image is 300% of the element, so 100% = -2x the element and 150% = -3x =
 * exactly one tile. Hence 150%, not 100%.
 */
@keyframes wensity-text-spectrum-h {
  0% { background-position: 0% 50%; }
  100% { background-position: 150% 50%; }
}
@keyframes wensity-text-spectrum-v {
  0% { background-position: 50% 0%; }
  100% { background-position: 50% 150%; }
}
@keyframes wensity-text-spectrum-d {
  0% { background-position: 0% 0%; }
  100% { background-position: 150% 150%; }
}
@media (prefers-reduced-motion: reduce) {
  .wensity-text-spectrum {
    animation: none !important;
    background-position: 50% 50% !important;
  }
}
`;
